mapper.select:
select
	g.id, g.module_lv1, g.module_lv2, g.module_lv3,
	g.analysis_dimension, g.detail_dimension, g.reserve_column,
	g.data_type, g.data_time, g.start_time, g.end_time, g.description,
	g.evaluation_analysis_file, g.create_by, g.create_code, g.create_time,
	g.original_filenames, g.new_file_names, g.status, g.evaluation_analysis
from
	(select * from gac_evaluation_analysis gt
	where gt.deleted = b'0'
	
		AND gt.module_lv1 = #{moduleLv1}
	
	
		AND gt.module_lv2 = #{moduleLv2}
	
	
		AND gt.module_lv3 = #{moduleLv3}
	
	
		AND gt.analysis_dimension = #{analysisDimension}
	
	
		AND gt.detail_dimension = #{detailDimension}
	
	
		AND reserve_column = #{reserveColumn}
	
	
		AND gt.data_type = #{dataType}
	
	
		AND gt.data_time = #{dataTime}
	
	
		AND gt.start_time = #{startTime}
	
	
		AND gt.end_time = #{endTime}
	
	
		AND gt.status = #{status}
	
	) g
INNER JOIN (
	SELECT
		
			module_lv1
		
		
			,module_lv2
		
		
			,module_lv3
		
		
			,analysis_dimension
		
		
			,detail_dimension
		
		
			,reserve_column
		
		
			,data_type
		
		
			,data_time
		
		
			,start_time
		
		
			,end_time
		
		
			,status
		
		,MAX(create_time) AS latest
	FROM gac_evaluation_analysis
	WHERE deleted = '0'
		
			AND module_lv1 = #{moduleLv1}
		
		
			AND module_lv2 = #{moduleLv2}
		
		
			AND module_lv3 = #{moduleLv3}
		
		
			AND analysis_dimension = #{analysisDimension}
		
		
			AND detail_dimension = #{detailDimension}
		
		
			AND reserve_column = #{reserveColumn}
		
		
			AND data_type = #{dataType}
		
		
			AND data_time = #{dataTime}
		
		
			AND start_time = #{startTime}
		
		
			AND end_time = #{endTime}
		
		
			AND status = #{status}
		
	GROUP BY
			module_lv1
		
			,module_lv2
		
		
			,module_lv3
		
		
			,analysis_dimension
		
		
			,detail_dimension
		
		
			,reserve_column
		
		
			,data_type
		
		
			,data_time
		
		
			,start_time
		
		
			,end_time
		
		
			,status
		
	) AS latest_records
ON
	g.create_time = latest_records.latest
	
		AND g.module_lv1 = latest_records.module_lv1
	
	
		AND g.module_lv2 = latest_records.module_lv2
	
	
		AND g.module_lv3 = latest_records.module_lv3
	
	
		AND g.analysis_dimension = latest_records.analysis_dimension
	
	
		AND g.detail_dimension = latest_records.detail_dimension
	
	
		AND g.reserve_column = latest_records.reserve_column
	
	
		AND g.data_type = latest_records.data_type
	
	
		AND g.data_time = latest_records.data_time
	
	
		AND g.start_time = latest_records.start_time
	
	
		AND g.end_time = latest_records.end_time
	
	
		AND g.status = latest_records.status
